SourceCode.Declaration:
/// <summary>
/// Batch controller class for Post sales order shipment processing
/// </summary>
class METSalesOrderShipmentConfirmationController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>New Controller Object</returns>
public static METSalesOrderShipmentConfirmationController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METSalesOrderShipmentConfirmationController controller = new METSalesOrderShipmentConfirmationController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METSalesOrderShipmentConfirmationService), methodstr(METSalesOrderShipmentConfirmationService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    METSalesOrderShipmentConfirmationController     controller;
    METSalesOrderShipmentConfirmationContract       contract;
    List                                            shipIdList = new List(Types::String);
    METThreadCount                                  threadCount = WHSParameters::find().METFinalisationThreadCount;
    str                                             listOfShipment;

    if (threadCount == 0)
    {
        throw error("@MET:ThreadCheck");
    }

    // create controller
    controller = METSalesOrderShipmentConfirmationController::construct(_args);

    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    controller.parmShowDialog(false);

    if (_args.menuItemName() == menuItemActionStr(METSalesOrderShipmentConfirmationController))
    {
        FormRun     formRun = _args.caller();            
        Map         map = formRun.getFinalizationHeaderMap();

        if (map.empty())
        {
            throw error("@MET:NoRecordUpdate");
        }

        MapIterator mapIterator = new MapIterator(map);
        METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
        FormDataSource      metSalesOrderShipmentHeaderDS;
        FormDataSource      metSalesOrderShipmentLinesDS;

        metSalesOrderShipmentHeaderDS = formRun.dataSource(formDataSourceStr(METSalesOrderFinalizationWorkbench, METSalesOrderShipmentLoadHeader)) as FormDataSource;
        metSalesOrderShipmentLinesDS = formRun.dataSource(formDataSourceStr(METSalesOrderFinalizationWorkbench, METSalesOrderShipmentLoadLines)) as FormDataSource;

        ttsbegin;

        while (mapIterator.more())
        {
            metSalesOrderShipmentLoadHeader = METSalesOrderShipmentLoadHeader::findByRecId(mapIterator.key(), true);

            metSalesOrderShipmentLoadHeader.checkAndUpdateCCR();/*Condition added based on CB231*/

            if (metSalesOrderShipmentLoadHeader.RecId &&
                metSalesOrderShipmentLoadHeader.ShipmentStatus != MetShipmentStatus::Shipped    &&
                metSalesOrderShipmentLoadHeader.isValidShipmentToShipped()                      && 
                metSalesOrderShipmentLoadHeader.isSOLineRelatedTORecevied())
            {
                shipIdList.addEnd(metSalesOrderShipmentLoadHeader.ShipmentId);

                listOfShipment += ' | ' + metSalesOrderShipmentLoadHeader.ShipmentId;

                metSalesOrderShipmentLoadHeader.ShipmentStatus = MetShipmentStatus::Loaded;
                metSalesOrderShipmentLoadHeader.update();

                Info(strFmt("@MET:ShipmentUpdateMsg", metSalesOrderShipmentLoadHeader.ShipmentId, metSalesOrderShipmentLoadHeader.ShipmentStatus));

                metSalesOrderShipmentLoadHeader::updateLoadStatus(metSalesOrderShipmentLoadHeader.LoadId);
            }
            else
            {
                error(strFmt("@MET:InvalidShipment", metSalesOrderShipmentLoadHeader.ShipmentId));
            }
            mapIterator.next();
        }
        ttscommit;

        threadCount = METSalesOrderShipmentConfirmationController::calcThreadCount(shipIdList, threadCount);

        if(!shipIdList.empty())
        {
            contract = controller.getDataContractObject('_contract') as METSalesOrderShipmentConfirmationContract;
            contract.parmShipmentIdList(shipIdList);
            contract.parmThreadCount(threadCount);
            controller.parmDialogCaption(strFmt("@MET:ShipmentConfirm", listOfShipment));
            controller.batchInfo().parmBatchExecute(true);
            controller.startOperation();
        }
        formRun.cleanupMarkMap(map, true);

        metSalesOrderShipmentHeaderDS.executeQuery();
        metSalesOrderShipmentHeaderDS.research(true);

        SysQuery::findOrCreateRange(metSalesOrderShipmentLinesDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadLines, RecId)).value(queryValue(0));
    }
    else
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }
}

/// <summary>
/// This method will get the thread count based on the shipment id list and max thread count
/// </summary>
/// <param name = "_shipmentIdList">ShipmentList</param>
/// <param name = "_maxThreadCount">MaxThreadCount</param>
/// <returns>ThreadCount</returns>
public static METThreadCount calcThreadCount(List _shipmentIdList, METThreadCount _maxThreadCount)
{
    METSalesOrderShipmentLoadHeader shipmentLoadHeader;
    METSalesOrderShipmentLoadLines  shipmentLoadLines;
    ListEnumerator                  enumerator          = _shipmentIdList.getEnumerator();
    boolean                         runByOrder          = WHSParameters::find().METRunShipmentConfirmationByOrder;
    int                             workItemCount;

    while (enumerator.moveNext() && workItemCount < _maxThreadCount)
    {
        MetShipmentId shipmentId = enumerator.current();

        select firstonly CustAccount from shipmentLoadHeader
        where shipmentLoadHeader.ShipmentId == shipmentId;

        if (runByOrder
        && METCustTable::find(shipmentLoadHeader.CustAccount).FinalizationDocument != METFinalizationDocument::None)
        {
            // One work item per order of the shipment
            while select OrderNum from shipmentLoadLines
                group by OrderNum
                where shipmentLoadLines.ShipmentId == shipmentId
            {
                workItemCount++;

                if (workItemCount >= _maxThreadCount)
                {
                    break;
                }
            }
        }
        else
        {
            // One work item for the whole shipment
            workItemCount++;
        }
    }

    return max(1, min(_maxThreadCount, workItemCount));
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:ConfirmShipment";
}
